// Tramage ordonné (matrice de Bayer 8x8) : réduit l'image à quelques niveaux.
float bayer2(vec2 a){ a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }
float bayer4(vec2 a){ return bayer2(0.5 * a) * 0.25 + bayer2(a); }
float bayer8(vec2 a){ return bayer4(0.5 * a) * 0.25 + bayer2(a); }
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
void mainImage(out vec4 o, in vec2 p){
  float size = max(1.0, floor(uParam0 + 0.5));
  vec2 cell = floor(p / size);
  vec2 uv = (cell + 0.5) * size / iResolution.xy;
  vec3 src = texture(iChannel0, uv).rgb;
  float levels = max(2.0, floor(uParam1 + 0.5));
  float thr = bayer8(cell) - 0.5;
  vec3 v = mix(vec3(lum(src)), src, uParam2);
  vec3 q = floor((v + thr / (levels - 1.0)) * (levels - 1.0) + 0.5) / (levels - 1.0);
  o = vec4(clamp(q, 0.0, 1.0), 1.0);
}

// Similigravure : points dont la taille suit la luminance, grille inclinée.
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
void mainImage(out vec4 o, in vec2 p){
  float s = max(3.0, uParam0);
  float a = uParam1;
  mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
  vec2 q = (R * p) / s;
  vec2 g = floor(q) + 0.5;
  vec2 f = fract(q) - 0.5;
  vec2 centre = (g * s) * R;          // R est orthonormale : v * R = transpose(R) * v
  vec3 src = texture(iChannel0, clamp(centre / iResolution.xy, 0.0, 1.0)).rgb;
  float r = sqrt(1.0 - lum(src)) * 0.7071;
  float m = 1.0 - smoothstep(r - 0.1, r, length(f));
  vec3 ink = mix(vec3(0.0), src, uParam2);
  o = vec4(mix(vec3(1.0), ink, m), 1.0);
}

// Détecteur de coins de Harris (une passe, fenêtre gaussienne 5x5, k = 0,05).
// Pas de suppression des non-maxima (il faudrait une seconde passe) : les coins apparaissent comme des taches.
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
float L(vec2 uv){ return lum(texture(iChannel0, uv).rgb); }
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec2 t = max(uParam0, 1.0) / iChannelResolution[0].xy;
  float sxx = 0.0, syy = 0.0, sxy = 0.0;
  for (int j = -2; j <= 2; j++) {
    for (int i = -2; i <= 2; i++) {
      vec2 q = uv + t * vec2(float(i), float(j));
      float ix = L(q + vec2(t.x, 0.0)) - L(q - vec2(t.x, 0.0));
      float iy = L(q + vec2(0.0, t.y)) - L(q - vec2(0.0, t.y));
      float w = exp(-float(i * i + j * j) / 4.0);
      sxx += w * ix * ix; syy += w * iy * iy; sxy += w * ix * iy;
    }
  }
  float det = sxx * syy - sxy * sxy;
  float tr = sxx + syy;
  float r = (det - 0.05 * tr * tr) * uParam1;
  float corner = smoothstep(uParam2, uParam2 + 0.25, r);
  vec3 base = texture(iChannel0, uv).rgb;
  o = vec4(mix(base * 0.55, vec3(1.0, 0.25, 0.1), corner), 1.0);
}

// Transformée de Hough des cercles de rayon fixe, en une passe.
// Entrée (canal 0) : une CARTE DE CONTOURS (sonic-shader sobel en mode 0, channel0="#contours").
// Chaque pixel de sortie est un centre candidat : son score est la moyenne des contours sur le cercle
// de rayon uParam0 (en hauteurs d'image) autour de lui. Pic lumineux = centre d'un cercle de ce rayon.
// Coût : 64 lectures par pixel.
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  float asp = iChannelResolution[0].x / iChannelResolution[0].y;
  vec2 ext = vec2(asp, 1.0);
  vec2 c = (uv - 0.5) * ext;
  float r = max(uParam0, 0.01);
  float acc = 0.0;
  for (int k = 0; k < 64; k++) {
    float a = (float(k) + 0.5) / 64.0 * 6.2831853;
    vec2 q = (c + r * vec2(cos(a), sin(a))) / ext + 0.5;
    if (q.x >= 0.0 && q.x <= 1.0 && q.y >= 0.0 && q.y <= 1.0) acc += dot(texture(iChannel0, q).rgb, vec3(0.3333));
  }
  float v = clamp((acc / 64.0) * uParam1 - uParam2, 0.0, 1.0);
  vec3 edges = vec3(dot(texture(iChannel0, uv).rgb, vec3(0.3333)));
  vec3 hot = vec3(clamp(v * 3.0, 0.0, 1.0), clamp(v * 3.0 - 1.0, 0.0, 1.0), clamp(v * 3.0 - 2.0, 0.0, 1.0));
  o = vec4(max(hot, edges * 0.35 * step(0.5, uParam3)), 1.0);
}

// Transformée de Hough des droites, en une passe (force brute le long de chaque droite).
// Entrée (canal 0) : une CARTE DE CONTOURS, par exemple un sonic-shader sobel en mode 0 (channel0="#contours").
// Sortie : l'espace de Hough. x = angle theta (0..pi), y = distance rho (-R..R) depuis le centre de l'image.
// Un point lumineux = une droite de l'image (theta, rho). Pas de détection de pics (il faudrait une seconde passe).
// Coût : 96 lectures par pixel de sortie : afficher en petit (par ex. 360 x 240).
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  float asp = iChannelResolution[0].x / iChannelResolution[0].y;
  vec2 ext = vec2(asp, 1.0);
  float rmax = 0.5 * length(ext);
  float th = uv.x * 3.14159265;
  float rho = (uv.y * 2.0 - 1.0) * rmax;
  vec2 n = vec2(cos(th), sin(th));
  vec2 d = vec2(-n.y, n.x);
  float acc = 0.0;
  float cnt = 0.0;
  for (int k = 0; k < 96; k++) {
    float s = ((float(k) + 0.5) / 96.0 * 2.0 - 1.0) * rmax;
    vec2 q = (rho * n + s * d) / ext + 0.5;
    if (q.x >= 0.0 && q.x <= 1.0 && q.y >= 0.0 && q.y <= 1.0) {
      acc += dot(texture(iChannel0, q).rgb, vec3(0.3333));
      cnt += 1.0;
    }
  }
  float v = cnt > 8.0 ? acc / cnt : 0.0;
  v = clamp((v * uParam0 - uParam1) / max(1.0 - uParam1, 0.001), 0.0, 1.0);
  vec3 hot = vec3(clamp(v * 3.0, 0.0, 1.0), clamp(v * 3.0 - 1.0, 0.0, 1.0), clamp(v * 3.0 - 2.0, 0.0, 1.0));
  o = vec4(hot, 1.0);
}

// Kaléidoscope sur l'image du canal 0 (caméra, vidéo, image).
void mainImage(out vec4 c, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec2 q = uv - 0.5; q.x *= iResolution.x / iResolution.y;
  float n = max(2.0, floor(uParam0 + 0.5));
  float a = atan(q.y, q.x) + iTime * uParam1; float r = length(q);
  a = mod(a, 6.2831853 / n); a = abs(a - 3.1415926 / n);
  uv = 0.5 + r * vec2(cos(a) * iResolution.y / iResolution.x, sin(a));
  c = vec4(texture(iChannel0, uv).rgb, 1.0);
}

// Pixels : mosaïque avec joints, résolution réglable.
void mainImage(out vec4 c, in vec2 p){
  vec2 uv = p / iResolution.xy;
  float n = max(8.0, uParam0);
  vec2 cells = vec2(n, n * iResolution.y / iResolution.x);
  vec2 q = (floor(uv * cells) + 0.5) / cells;
  vec3 col = texture(iChannel0, q).rgb;
  vec2 f = fract(uv * cells) - 0.5;
  col *= 1.0 - smoothstep(0.42, 0.5, max(abs(f.x), abs(f.y)));
  c = vec4(col, 1.0);
}

// Plasma : ondes colorées, le clic déplace le centre.
vec3 pal(float t){ return 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67))); }
void mainImage(out vec4 o, in vec2 f){
  vec2 p = (2.0 * f - iResolution.xy) / min(iResolution.x, iResolution.y);
  float t = iTime * uParam0;
  float s = uParam1;
  vec2 m = iMouse.z > 0.0 ? (2.0 * iMouse.xy - iResolution.xy) / min(iResolution.x, iResolution.y) : vec2(0.0);
  float v = sin(p.x * s + t) + sin(p.y * s * 1.3 - t * 1.1)
          + sin((p.x + p.y) * s * 0.7 + t * 0.7) + sin(length(p - m) * s * 1.6 - t * 1.4);
  vec3 col = pal(uParam2 + v * 0.15);
  col *= 0.75 + 0.25 * sin(v * 3.14159);
  o = vec4(col, 1.0);
}

// Contours de Sobel sur l'image du canal 0.
// Modes : 0 = contours blancs sur noir (sortie utilisable comme carte de contours
// par hough-lines / hough-circles), 1 = contours par-dessus l'image, 2 = direction du gradient en couleur.
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
float L(vec2 uv){ return lum(texture(iChannel0, uv).rgb); }
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec2 t = max(uParam0, 1.0) / iChannelResolution[0].xy;
  float a = L(uv + t * vec2(-1.0, -1.0)), b = L(uv + t * vec2(0.0, -1.0)), c = L(uv + t * vec2(1.0, -1.0));
  float d = L(uv + t * vec2(-1.0, 0.0)),                                   f = L(uv + t * vec2(1.0, 0.0));
  float g = L(uv + t * vec2(-1.0, 1.0)),  h = L(uv + t * vec2(0.0, 1.0)),  i = L(uv + t * vec2(1.0, 1.0));
  float gx = (c + 2.0 * f + i) - (a + 2.0 * d + g);
  float gy = (g + 2.0 * h + i) - (a + 2.0 * b + c);
  float m = clamp(length(vec2(gx, gy)) * uParam1, 0.0, 1.0);
  int mode = int(uParam2 + 0.5);
  vec3 base = texture(iChannel0, uv).rgb;
  vec3 col = vec3(m);
  if (mode == 1) col = mix(base * 0.6, vec3(1.0, 0.9, 0.2), m);
  if (mode == 2) {
    float h6 = atan(gy, gx) / 6.2831853 + 0.5;
    vec3 hue = clamp(abs(mod(h6 * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    col = hue * m;
  }
  o = vec4(col, 1.0);
}

// Fausse caméra thermique : luminance -> palette chaud/froid.
void mainImage(out vec4 c, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec3 col = texture(iChannel0, uv).rgb;
  float l = dot(col, vec3(0.299, 0.587, 0.114));
  vec3 t = clamp(vec3(1.6 * l - 0.3, sin(3.14159 * l) * 1.1, 1.0 - 1.8 * l), 0.0, 1.0);
  c = vec4(mix(col, t, uParam0), 1.0);
}
